package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.paiflow.domain.*;
import com.ruoyi.paiflow.mapper.DataMapper;
import java.time.LocalDateTime;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 固定资源、原行返回、幂等与当前权利核对；HTTP租约/数据库事务由整合测试另证。 */
class DataOperationTest {
    static final String RESOURCE="data:5:revision:2";
    static class Fixture {
        final DataMapper mapper=mock(DataMapper.class);final DataRuntimeCatalog catalog=mock(DataRuntimeCatalog.class);final DataResourceService rows=mock(DataResourceService.class);
        final DataOperationService operation=new DataOperationService(catalog,rows,mapper);final RunRecord run=new RunRecord();final DataRecord db=new DataRecord(),table=new DataRecord();final JSONObject descriptor;
        Fixture(){db.setId(5L);db.setDeleted(0);db.setRevision(2L);table.setId(7L);table.setDbId(5L);table.setDeleted(0);descriptor=JSONObject.of("tables",JSONObject.of("people",JSONObject.of("tableId",7L,"allowedModes",new JSONArray(List.of(0,1,2,3,4)),"execEnvs",new JSONArray(List.of(1,2)),"columns",new JSONArray(List.of("id","name","score")))));
            run.setId("33333333-3333-3333-3333-333333333333");run.setAttempt(1);run.setState("RUNNING");run.setSpaceId(2L);run.setOwnerUserId(1L);run.setExecutionStartedAt(LocalDateTime.now());run.setAssignmentJson(JSONObject.of("dataEnvironment",2,"effectPolicy",JSONObject.of("mode","approved_write","allowedOperations",new JSONArray(List.of("data.query","data.mutate")))).toJSONString());
            when(catalog.resolvePinned(2,1,RESOURCE,descriptor)).thenReturn(new DataRuntimeCatalog.FixedData(RESOURCE,descriptor,db,List.of(table)));when(mapper.lockDatabase(5)).thenReturn(db);when(mapper.lockTable(7)).thenReturn(table);when(mapper.request(anyString(),anyInt(),anyString())).thenReturn(null);when(mapper.record(anyString(),anyInt(),anyString(),anyString(),anyString())).thenReturn(1);
            when(rows.loadRows(7,2)).thenReturn(List.of(JSONObject.of("id",1,"name","甲","score",3),JSONObject.of("id",2,"name","乙","score",8)));
        }
        JSONObject query(){return JSONObject.of("mode",3,"table","people","execDev",2,"where",JSONObject.of("logicalOperator","and","conditions",new JSONArray(List.of(JSONObject.of("fieldName","score","operator",">","value",5)))),"values",new JSONObject(),"columns",new JSONArray(List.of("name")),"order",new JSONArray(),"limit",10);}
    }
    @Test void structuredQueryProjectsOriginalExecSuccess(){var f=new Fixture();var response=f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",f.query(),"node:1");assertEquals(0,response.getIntValue("code"));assertEquals(new JSONArray(List.of(JSONObject.of("name","乙"))),response.getJSONObject("data").getJSONArray("exec_success"));verify(f.mapper).record(eq(f.run.getId()),eq(1),anyString(),anyString(),anyString());verify(f.rows,never()).mutateRow(any(),anyInt(),anyInt(),any(),anyLong());}
    @Test void debugFixtureReadsOnlyCenterFixedTestEnvironment(){var f=new Fixture();var assignment=JSON.parseObject(f.run.getAssignmentJson());assignment.put("dataEnvironment",1);f.run.setAssignmentJson(assignment.toJSONString());when(f.rows.loadRows(7,1)).thenReturn(List.of(JSONObject.of("id",91,"name","测试样本","score",10)));var request=f.query();request.put("execDev",1);var response=f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",request,"debug1");assertEquals("测试样本",response.getJSONObject("data").getJSONArray("exec_success").getJSONObject(0).getString("name"));verify(f.rows).loadRows(7,1);verify(f.rows,never()).loadRows(7,2);assignment.remove("dataEnvironment");f.run.setAssignmentJson(assignment.toJSONString());assertThrows(ServiceException.class,()->f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",request,"legacy"));}
    @Test void writeUsesActualMatchingRowAndPersistsReceipt(){var f=new Fixture();var request=f.query();request.put("mode",2);request.put("values",JSONObject.of("name","修改"));when(f.rows.mutateRow(eq(f.table),eq(2),eq(2),any(),eq(1L))).thenAnswer(i->i.getArgument(3));var response=f.operation.execute(f.run,RESOURCE,f.descriptor,"data.mutate",request,"node:2");assertEquals("修改",response.getJSONObject("data").getJSONArray("exec_success").getJSONObject(0).getString("name"));verify(f.rows).mutateRow(f.table,2,2,JSONObject.of("name","修改","id",2),1);verify(f.rows,never()).mutateRow(eq(f.table),eq(1),anyInt(),any(),anyLong());}
    @Test void currentPermissionRevocationEnvironmentAndEffectMismatchPreventRows(){
        var revoked=new Fixture();doThrow(new ServiceException("撤销",403)).when(revoked.catalog).requireOwner(2,1,true);var write=revoked.query();write.put("mode",2);assertThrows(ServiceException.class,()->revoked.operation.execute(revoked.run,RESOURCE,revoked.descriptor,"data.mutate",write,"x"));verify(revoked.rows,never()).loadRows(anyLong(),anyInt());
        var env=new Fixture();var request=env.query();request.put("execDev",1);assertThrows(ServiceException.class,()->env.operation.execute(env.run,RESOURCE,env.descriptor,"data.query",request,"x"));verify(env.mapper,never()).lockTable(anyLong());
        var effects=new Fixture();effects.run.setAssignmentJson("{\"dataEnvironment\":2,\"effectPolicy\":{\"mode\":\"approved_write\",\"allowedOperations\":[\"variables.set\"]}}");var mutation=effects.query();mutation.put("mode",2);assertThrows(ServiceException.class,()->effects.operation.execute(effects.run,RESOURCE,effects.descriptor,"data.mutate",mutation,"x"));verify(effects.rows,never()).loadRows(anyLong(),anyInt());
    }
    @Test void identicalRetryReturnsSavedResponseDifferentPayloadRejects(){var f=new Fixture();var request=f.query();var saved=JSONObject.of("code",0,"message","success","data",JSONObject.of("exec_success",new JSONArray(List.of(JSONObject.of("name","saved")))));String hash=RunJsonBoundary.hashFull(JSONObject.of("resource",RESOURCE,"kind","data.query","payload",request));when(f.mapper.request(f.run.getId(),1,DataRuntimeCatalog.sha("retry"))).thenReturn(Map.of("requestHash",hash,"responseJson",saved.toJSONString()));assertEquals(saved,f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",request,"retry"));verify(f.rows,never()).loadRows(anyLong(),anyInt());request.put("limit",1);assertThrows(ServiceException.class,()->f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",request,"retry"));}
    @Test void customSqlReturnsRealProjectionAndCount(){var f=new Fixture();var sql=JSONObject.of("mode",0,"sql","SELECT name FROM people WHERE score >= 5","execDev",2);var result=f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",sql,"sql1");assertEquals(new JSONArray(List.of(JSONObject.of("name","乙"))),result.getJSONObject("data").getJSONArray("exec_success"));var count=JSONObject.of("mode",0,"sql","SELECT COUNT(*) AS total FROM people","execDev",2);assertEquals(2,f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",count,"sql2").getJSONObject("data").getJSONArray("exec_success").getJSONObject(0).getIntValue("total"));assertThrows(ServiceException.class,()->f.operation.execute(f.run,RESOURCE,f.descriptor,"data.mutate",sql,"wrongkind"));}
    @Test void originalNumberZeroEquivalentMatchesJsonIntegerZero(){var f=new Fixture();when(f.rows.loadRows(7,2)).thenReturn(List.of(JSONObject.of("id",3,"name","零值","score",0)));var request=f.query();request.put("where",JSONObject.of("logicalOperator","and","conditions",new JSONArray(List.of(JSONObject.of("fieldName","score","operator","null","zeroEquivalent",new java.math.BigDecimal("0.0"))))));var result=f.operation.execute(f.run,RESOURCE,f.descriptor,"data.query",request,"zero");assertEquals(new JSONArray(List.of(JSONObject.of("name","零值"))),result.getJSONObject("data").getJSONArray("exec_success"));}
}
